B.ati=new A.az(B.uw,["\u0414\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u044c","\u041f\u0430\u043d\u0435\u043b\u044c \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438","\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f \u043d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435 \u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0442 \u043d\u0430 \u0432\u0441\u0435\u0445 \u044d\u043a\u0440\u0430\u043d\u0430\u0445.","\u0420\u0430\u0437\u043c\u0435\u0440 \u0442\u0435\u043a\u0441\u0442\u0430","\u041c\u0435\u043d\u044c\u0448\u0435","\u0411\u043e\u043b\u044c\u0448\u0435","\u0412\u044b\u0441\u043e\u043a\u0438\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442","\u0416\u0438\u0440\u043d\u044b\u0439 \u0442\u0435\u043a\u0441\u0442","\u041c\u0435\u043d\u044c\u0448\u0435 \u0430\u043d\u0438\u043c\u0430\u0446\u0438\u0438","\u041f\u043e\u0434\u0447\u0451\u0440\u043a\u0438\u0432\u0430\u0442\u044c \u0441\u0441\u044b\u043b\u043a\u0438","\u042f\u0440\u043a\u043e\u0435 \u0432\u044b\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0444\u043e\u043a\u0443\u0441\u0430","\u0421\u0431\u0440\u043e\u0441\u0438\u0442\u044c \u0432\u0441\u0451","\u0417\u0430\u043a\u0440\u044b\u0442\u044c"],t.l)
